import{_ as n,C as t,o as r,c as d,j as a,a as l,E as i,a6 as c}from"./chunks/framework.CD0vXS2f.js";const b=JSON.parse('{"title":"04 · Cosmos DB Vector/Hybrid Search & Multi-Store Retrieval","description":"Architecting Azure Cosmos DB for NoSQL DiskANN vector and BM25 RRF hybrid search, partition-key tenant isolation, zero-downtime alias/re-embedding math, and corpus anti-poisoning flywheels.","frontmatter":{"title":"04 · Cosmos DB Vector/Hybrid Search & Multi-Store Retrieval","description":"Architecting Azure Cosmos DB for NoSQL DiskANN vector and BM25 RRF hybrid search, partition-key tenant isolation, zero-downtime alias/re-embedding math, and corpus anti-poisoning flywheels."},"headers":[],"relativePath":"playbooks/ai-data-strategy/04-cosmos-vector-hybrid-retrieval.md","filePath":"playbooks/ai-data-strategy/04-cosmos-vector-hybrid-retrieval.md","lastUpdated":1795642852816,"verifiedStamp":"2026-11-25 13:40 PST"}'),h={name:"playbooks/ai-data-strategy/04-cosmos-vector-hybrid-retrieval.md"};function p(g,e,u,m,k,y){const s=t("PlaybookMeta"),o=t("PageBrief");return r(),d("div",null,[e[0]||(e[0]=a("h1",{id:"_04-·-cosmos-db-vector-hybrid-search-multi-store-retrieval",tabindex:"-1"},[l("04 · Cosmos DB Vector/Hybrid Search & Multi-Store Retrieval "),a("a",{class:"header-anchor",href:"#_04-·-cosmos-db-vector-hybrid-search-multi-store-retrieval","aria-label":'Permalink to "04 · Cosmos DB Vector/Hybrid Search & Multi-Store Retrieval"'},"​")],-1)),i(s,{track:"05 · AI Data Strategy, Fabric–Foundry & Governance",verified:"2026-11-23 19:30 PST",status:"Live v2.0",studioHref:"/studio/#data-strategy",studioLabel:"Data Strategy Advisor →"}),i(o,{stage:"design",readTime:"6 min read",problem:"Teams either force high-churn agent memory into batch search indexes or deploy Cosmos DB vectors without DiskANN/partition-key design—triggering cross-partition RU explosions and container rebuild outages when embedding models change.",takeaway:"Use Azure Cosmos DB for NoSQL (DiskANN + BM25 FullTextScore via RRF) scoped by tenant/engagement partition keys for operational RAG and agent memory, pair it with Azure AI Search (Foundry IQ) for deep multi-document semantic reranking, and plan blue-green cutovers plus anti-poisoning scans from day one.",csaUse:"Use the Cosmos DB indexing policy, weighted RRF query template, and Azure vector store selection matrix below during data-store architecture reviews."}),e[1]||(e[1]=c('<h2 id="_1-azure-cosmos-db-for-nosql-vector-diskann-hybrid-rrf-architecture-m" tabindex="-1">1. Azure Cosmos DB for NoSQL: Vector (<code>DiskANN</code>) &amp; Hybrid (<code>RRF</code>) Architecture <code>[M]</code> <a class="header-anchor" href="#_1-azure-cosmos-db-for-nosql-vector-diskann-hybrid-rrf-architecture-m" aria-label="Permalink to &quot;1. Azure Cosmos DB for NoSQL: Vector (`DiskANN`) &amp; Hybrid (`RRF`) Architecture `[M]`&quot;">​</a></h2><p><strong>Azure Cosmos DB for NoSQL</strong> colocates operational JSON documents, agent conversation checkpoints (Playbook 03 <code>Model 2</code> stateless tier), full-text tokens (<code>BM25</code>), and high-dimensional vector embeddings inside the <strong>same container and partition</strong> <span class="ev-badge ev-m">[M]</span>. This eliminates dual-write synchronization lag between an operational store and a separate vector database for real-time agent memory, episodic recall, and tenant-scoped operational RAG.</p><h3 id="choosing-the-right-cosmos-db-vector-index-policy-m" tabindex="-1">Choosing the Right Cosmos DB Vector Index Policy <code>[M]</code> <a class="header-anchor" href="#choosing-the-right-cosmos-db-vector-index-policy-m" aria-label="Permalink to &quot;Choosing the Right Cosmos DB Vector Index Policy `[M]`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Vector Index Type</th><th style="text-align:left;">Underlying Algorithm</th><th style="text-align:left;">Best-Fit Workload</th><th style="text-align:left;">Trade-Offs &amp; Guardrails</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>flat</code></strong></td><td style="text-align:left;">Exact brute-force <code>kNN</code> (<code>100%</code> recall)</td><td style="text-align:left;">Small, tightly partitioned tenant/engagement buckets (<code>&lt;= ~50K</code> vectors per partition)</td><td style="text-align:left;">Highest exact recall; RU cost scales linearly if partition grows unbounded <span class="ev-badge ev-m">[M]</span>.</td></tr><tr><td style="text-align:left;"><strong><code>quantizedFlat</code></strong></td><td style="text-align:left;">DiskANN-based vector quantization + <code>kNN</code></td><td style="text-align:left;">Medium-sized scoped partitions needing lower RU and memory footprint</td><td style="text-align:left;">Compressed vectors improve scan efficiency over unquantized <code>flat</code> <span class="ev-badge ev-m">[M]</span>.</td></tr><tr><td style="text-align:left;"><strong><code>diskANN</code></strong></td><td style="text-align:left;">Microsoft Research DiskANN graph ANN index</td><td style="text-align:left;">High-scale, multi-modal vector/hybrid search (<code>100K</code> to <code>100M+</code> vectors) with predictable low latency</td><td style="text-align:left;">Best RU efficiency at scale; pair with tenant partition keys (<code>WHERE</code> / <code>partitionKey</code>) for single-partition execution <span class="ev-badge ev-m">[M]</span>.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Critical Platform Immutability Rule (<code>Gate D7</code>) <code>[M]</code></p><p>In Azure Cosmos DB for NoSQL, <strong>vector policies and vector indexes are immutable after container creation</strong> <span class="ev-badge ev-m">[M]</span>. Changing <code>dimensions</code> (for example migrating <code>1536 → 3072</code>), <code>dataType</code>, or <code>distanceFunction</code> requires creating a <strong>new container</strong>, backfilling embeddings via Change Feed / batch pipeline, and executing a <strong>blue-green config swap</strong>—never an in-place schema migration <span class="ev-badge ev-arch">[Arch]</span>.</p></div><p>The <a href="https://learn.microsoft.com/en-us/azure/cosmos-db/vector-search#vector-indexing-policies" target="_blank" rel="noreferrer">published vector-index limits</a> are <strong>505 dimensions</strong> for <code>flat</code> and <strong>4,096 dimensions</strong> for <code>quantizedFlat</code> / <code>diskANN</code> <span class="ev-badge ev-m">[M]</span>. The <a href="./05-data-governance-release-gates#cosmos-dimension-limits">offline <code>DRG005</code> dimension check</a> blocks snapshots exceeding the selected index&#39;s limit; the Studio&#39;s <code>1536</code> / <code>3072</code> presets cannot be used with a <code>flat</code> index <span class="ev-badge ev-arch">[Arch]</span>.</p><h3 id="production-weighted-hybrid-query-pattern-diskann-bm25-rrf-m" tabindex="-1">Production Weighted Hybrid Query Pattern (<code>DiskANN</code> + <code>BM25</code> + <code>RRF</code>) <code>[M]</code> <a class="header-anchor" href="#production-weighted-hybrid-query-pattern-diskann-bm25-rrf-m" aria-label="Permalink to &quot;Production Weighted Hybrid Query Pattern (`DiskANN` + `BM25` + `RRF`) `[M]`&quot;">​</a></h3><p>Combine <code>VectorDistance</code> and <code>FullTextScore</code> inside <code>ORDER BY RANK RRF(...)</code>, optionally weighting semantic vectors higher than keyword BM25 (for example <code>[2, 1]</code>). Always execute with an explicit <strong>tenant/engagement partition key</strong> and <code>tombstoned = false</code> predicate:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Execute with explicit RequestOptions.PartitionKey = &quot;tenant-alpha::eng-4812&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TOP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @topK</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">chunk_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sensitivity_label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">content</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tombstoned</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> false</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ARRAY_CONTAINS(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">acl_group_ids</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, @callerGroupId)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RANK RRF(</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    VectorDistance(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">vector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, @queryVector),</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FullTextScore(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, @kw1, @kw2),</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    [2, 1]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><blockquote><p><strong>Dialect Guardrail <code>[M]</code>:</strong> <code>RRF()</code> is valid only inside an <code>ORDER BY RANK</code> clause (it cannot be combined with a secondary <code>ORDER BY</code> on another path or projected in <code>SELECT</code>) and requires both the Cosmos DB <strong>Vector Index</strong> and <strong>Full-Text Index</strong> policies configured on the container <span class="ev-badge ev-m">[M]</span>.</p></blockquote><hr><h2 id="_2-authoritative-azure-ai-data-store-selection-matrix-m-arch" tabindex="-1">2. Authoritative Azure AI Data Store Selection Matrix <code>[M]</code> <code>[Arch]</code> <a class="header-anchor" href="#_2-authoritative-azure-ai-data-store-selection-matrix-m-arch" aria-label="Permalink to &quot;2. Authoritative Azure AI Data Store Selection Matrix `[M]` `[Arch]`&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Capability / Dimension</th><th style="text-align:left;"><strong>Microsoft Fabric / OneLake + Fabric IQ</strong></th><th style="text-align:left;"><strong>Azure AI Search (<code>Foundry IQ</code> MCP)</strong></th><th style="text-align:left;"><strong>Azure Cosmos DB for NoSQL (<code>DiskANN</code> + <code>RRF</code>)</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Primary Grounding Role</strong></td><td style="text-align:left;">Structured analytics, KPIs, Power BI Semantic Models, Delta Lakehouses &amp; Ontologies <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Enterprise unstructured document corpora, multi-step agentic query planning &amp; deep semantic reranking <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Real-time operational RAG, agent thread/episodic memory, high-churn user/tenant records <span class="ev-badge ev-m">[M]</span>.</td></tr><tr><td style="text-align:left;"><strong>Hybrid Search &amp; Reranking</strong></td><td style="text-align:left;">SQL / DAX / KQL exact execution + Semantic Model relationships.</td><td style="text-align:left;">Native BM25 + HNSW Vector + L2 <strong>Semantic Reranker</strong> + Foundry IQ query decomposition <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Native BM25 <code>FullTextScore</code> + <code>DiskANN</code> <code>VectorDistance</code> via weighted <code>RRF</code> (semantic reranker in preview) <span class="ev-badge ev-m">[M]</span>.</td></tr><tr><td style="text-align:left;"><strong>Multi-Tenant / Ethical-Wall Isolation</strong></td><td style="text-align:left;">OneLake Security + Workspace/Domain isolation + Power BI RLS/OLS <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Mandatory <code>acl_group_ids</code> OData trimming + dedicated per-tier index when required (<code>D5</code>).</td><td style="text-align:left;">Native single-partition isolation via <code>/tenantEngagementId</code> (or hierarchical partition keys) (<code>D7</code>).</td></tr><tr><td style="text-align:left;"><strong>Multi-Region Continuity (<a href="/enterprise-azure-ai-hub/playbooks/multi-region-bcp/04-stateful-stamp-failover">Playbook 03</a>)</strong></td><td style="text-align:left;">OneLake BCDR + regional capacity planning.</td><td style="text-align:left;">Independent regional Search stamps fed from <code>RA-GZRS</code> ADLS / OneLake (<code>&lt;1%</code> lag).</td><td style="text-align:left;">Native multi-region replication &amp; multi-region writes with <code>PreferredLocations</code> SDK failover <span class="ev-badge ev-m">[M]</span>.</td></tr><tr><td style="text-align:left;"><strong>Primary Scaling / Cost Lever</strong></td><td style="text-align:left;">Dedicated Interactive <strong>F-SKU</strong> CU headroom (<code>&lt;=65%</code> steady utilization).</td><td style="text-align:left;">Search Units (<code>Replicas × Partitions</code>) + Semantic Ranker query volume.</td><td style="text-align:left;">Autoscale <strong>RU/s</strong> (keep hybrid queries single-partition to avoid <code>10×–50×</code> cross-partition RU fan-out).</td></tr></tbody></table><hr><h2 id="_3-zero-downtime-alias-cutover-re-embedding-surge-math-gate-d8" tabindex="-1">3. Zero-Downtime Alias Cutover &amp; Re-Embedding Surge Math (<code>Gate D8</code>) <a class="header-anchor" href="#_3-zero-downtime-alias-cutover-re-embedding-surge-math-gate-d8" aria-label="Permalink to &quot;3. Zero-Downtime Alias Cutover &amp; Re-Embedding Surge Math (`Gate D8`)&quot;">​</a></h2><p>When upgrading an embedding model, tuning chunk overlap, or migrating Cosmos DB vector dimensions:</p><ol><li><strong>Compute Re-Embedding Token Volume Before Starting:</strong></li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TotalTokens     = Documents × AvgChunksPerDoc × AvgTokensPerChunk</span></span>\n<span class="line"><span>BackfillMinutes = TotalTokens ÷ (EmbeddingTPMQuota × 0.80)</span></span></code></pre></div><p><em>Example:</em> <code>250,000</code> documents × <code>18</code> chunks × <code>512</code> tokens = <strong><code>2.304B</code> embedding tokens</strong>. At a <code>1,000,000 TPM</code> batch embedding quota (<code>80%</code> usable ceiling = <code>800K TPM</code>), full backfill requires <strong><code>~48 hours</code></strong>—which would cause catastrophic downtime if executed in place against a live index! 2. <strong>Route Backfills Through Dedicated Batch Quotas:</strong> Never share your interactive inference or live ingestion APIM quota with multi-billion-token re-embedding jobs (<a href="/enterprise-azure-ai-hub/playbooks/apim-gateway/04-finops-token-governance">Playbook 02</a>). 3. <strong>Swap Atomically via Alias / Blue-Green Cutover:</strong></p><ul><li><strong>Azure AI Search:</strong> Build <code>kb-prod-v2</code>, verify document count &amp; recall parity against <code>kb-prod-v1</code>, then atomically repoint the <strong>Index Alias</strong> (<code>kb-prod-live → kb-prod-v2</code>) <span class="ev-badge ev-m">[M]</span>.</li><li><strong>Azure Cosmos DB:</strong> Provision <code>memory-v2</code> with the updated immutable <code>DiskANN</code> vector policy, backfill via Change Feed Processor, verify count/hybrid recall parity, and switch the active container binding in App Configuration / Key Vault <span class="ev-badge ev-arch">[Arch]</span>.</li></ul><p>The <a href="/enterprise-azure-ai-hub/studio/#data-strategy">Data Strategy Advisor</a> accepts only its numeric <code>1,536</code> and <code>3,072</code> embedding-dimension presets for sizing. Unsupported values hide capacity estimates and block CLI copying, including direct copy-handler invocation; a linked field error identifies the invalid selection. Governance contract JSON and the readiness simulation remain independent of sizing. This is a local calculator preset boundary, not an Azure service dimension limit <span class="ev-badge ev-arch">[Arch]</span>.</p><p>Offline interaction tests cover unsupported values and types, combined numeric/selector errors, recovery to both presets, unchanged contract/CLI exports, and preserved backfill and vector-memory estimates. They run in <code>npm run check:studio</code> and <code>npm run verify</code> without live Azure access <span class="ev-badge ev-val">[Validate]</span>.</p><hr><h2 id="_4-layout-aware-ingestion-anti-poisoning-eval-flywheel-gates-d9–d12" tabindex="-1">4. Layout-Aware Ingestion, Anti-Poisoning &amp; Eval Flywheel (<code>Gates D9–D12</code>) <a class="header-anchor" href="#_4-layout-aware-ingestion-anti-poisoning-eval-flywheel-gates-d9–d12" aria-label="Permalink to &quot;4. Layout-Aware Ingestion, Anti-Poisoning &amp; Eval Flywheel (`Gates D9–D12`)&quot;">​</a></h2><ul><li><strong>Layout-Aware Chunking (<code>Gate D9</code>):</strong> Convert PDFs, spreadsheets, and slide decks through <strong>Azure AI Content Understanding</strong> into layout-preserving Markdown so Markdown tables stay intact inside bounded chunks (<code>256–1,024</code> tokens) with deterministic <code>chunk_sha256</code> identifiers <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>Corpus Anti-Poisoning &amp; Indirect Injection Hygiene (<code>Gate D10</code>):</strong> Scan ingested text <em>before</em> indexing for instruction-override payloads (e.g., hidden white-on-white <code>&quot;ignore previous instructions&quot;</code>, <code>&quot;exfiltrate system prompt&quot;</code>, or unauthorized tool-invocation directives) and quarantine flagged documents rather than polluting shared vector indexes (<code>DRG006</code>) <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>Pos 6 Cache-Safe Retrieval Ordering (<code>Gate D11</code>):</strong> Sort retrieved citations deterministically by <code>(score desc, chunk_id asc)</code> and inject them strictly in <strong>Position 6</strong> after <code>Pos 1–3</code> static instructions and sorted <code>tools[]</code>—preserving Playbook 01 prefix cache reuse across multi-turn reasoning loops <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>OTel-to-Fabric Gold Eval Flywheel (<code>Gate D12</code>):</strong> Stream anonymized <code>gen_ai.*</code> telemetry and retrieval metrics (zero-result queries, low citation coverage, high Cosmos RU spikes, user thumbs-down signals) from Application Insights into a <strong>Microsoft Fabric OneLake Gold</strong> evaluation table so every quarterly retrieval regression becomes a permanent regression fixture for <code>agent_release_gate.py</code> and Foundry Evals <span class="ev-badge ev-arch">[Arch]</span> <span class="ev-badge ev-agree">[Agree]</span>.</li></ul>',25))])}const f=n(h,[["render",p]]);export{b as __pageData,f as default};
